class Postal:
    """Paper mail (docs/postal.md): letters from a .letter.tsx and postcards from a .postcard.tsx in your files, and mailboxes that receive and scan mail."""

    def __init__(self, t: Any) -> None:
        self._t = t

    def quote(self, source: str, *, provider: Optional[Literal["lob", "click2mail"]] = None, owner_id: Optional[str] = None) -> Any:
        """What mailing the letter or postcard would cost, and how it would go (its choices: the providers that can mail it). Costs nothing.

        Keyword arguments:
            provider: Who prints and posts it: lob (the default; the US and every other country) or click2mail (US only). Omitted: automatic, the best provider for the destination in the account's postal.providers order, Lob first.
            owner_id: An organisation's id, to act for it. Omitted: your own account.
        """
        a = _prune({"source": source})
        a.update(_prune({"provider": provider, "ownerId": owner_id}))
        return self._t.call("postal_quote", a)

    def send(self, source: str, *, provider: Optional[Literal["lob", "click2mail"]] = None, owner_id: Optional[str] = None) -> Any:
        """Mail the letter or postcard: charged first, recorded before it is sent, never retried. An agent needs a postal grant.

        Keyword arguments:
            provider: Who prints and posts it: lob (the default; the US and every other country) or click2mail (US only). Omitted: automatic, the best provider for the destination in the account's postal.providers order, Lob first.
            owner_id: An organisation's id, to act for it. Omitted: your own account.
        """
        a = _prune({"source": source})
        a.update(_prune({"provider": provider, "ownerId": owner_id}))
        return self._t.call("postal_send", a)

    def status(self, piece: Optional[str] = None) -> Any:
        """A sent piece's state and records; without a piece, the sent pieces."""
        a = _prune({"piece": piece})
        return self._t.call("postal_status", a)

    def cancel(self, piece: str) -> Any:
        """Cancel a piece before it is printed; the charge comes back."""
        a = _prune({"piece": piece})
        return self._t.call("postal_cancel", a)

    def inbox(self, mailbox: Optional[str] = None) -> Any:
        """Your mailboxes, or one mailbox's received pieces with their scans."""
        a = _prune({"mailbox": mailbox})
        return self._t.call("postal_inbox", a)


class Social:
    """A single connected social account, bound: cagi.social('tiktok', '@brand').post(fileId)."""

    def __init__(self, t: Any, platform: str, account: Optional[str] = None) -> None:
        self._t = t
        self.platform = platform
        self.account = account

    def post(self, file_id: str, **opts: Any) -> Any:
        """Publish a stored file to this account."""
        a = _prune({"integration": self.platform, "account": self.account, "fileId": file_id})
        a.update(_camel_keys(opts))
        return self._t.call("post", a)

    def call(self, method: str, path: str, **opts: Any) -> Any:
        """Raw API call as this account."""
        a = _prune({"integration": self.platform, "account": self.account, "method": method, "path": path})
        a.update(_camel_keys(opts))
        return self._t.call("integration_call", a)


